package dev.dwmir.lib.api;
import net.minecraft.client.MinecraftClient;import net.minecraft.client.gui.*;import net.minecraft.client.gui.screen.Screen;import net.minecraft.client.input.KeyInput;import net.minecraft.text.Text;import java.util.*;
/** HUD coordinates stay in game space; editor chrome uses a stable physical size. */
public class HudEditorScreen extends Screen implements PickerHost {
 private final Screen parent;private final java.util.List<HudElement> elements;private final Runnable save,test;private HudElement selected,drag;private boolean resizing,alphaDrag;private double offsetX,offsetY,startScale,startX,startY;private int originX,originY,popupX,popupY;private ColorPickerScreen picker;private float ui=1;private int uw,uh;
 public HudEditorScreen(Screen parent,java.util.List<HudElement> elements,Runnable save,Runnable test){super(Text.literal("HUD editor"));this.parent=parent;this.elements=elements;this.save=save;this.test=test;}
 protected boolean clickWorld(Click e,boolean twice){return false;}protected boolean dragWorld(Click e,double dx,double dy){return false;}protected boolean releaseWorld(Click e){return false;}protected boolean scrollWorld(double x,double y,double h,double v){return false;}
 protected boolean hasPicker(){return picker!=null;}protected String instruction(){return "Drag to move | Corner: size | Right: appearance";}
 private Click local(Click e){return new Click(e.x()/ui,e.y()/ui,e.buttonInfo());}
 public void openPicker(ColorPickerScreen p){picker=p;p.dismiss=()->{p.removed();picker=null;save.run();};p.init(uw,uh);}
 protected void init(){clearChildren();ui=(float)Math.min(1,2.0/MinecraftClient.getInstance().getWindow().getScaleFactor());uw=Math.round(width/ui);uh=Math.round(height/ui);int top=Math.round(48*ui);for(var e:elements){double cap=Math.min(5,Math.min((width-16.)/e.baseWidth(),(height-top-8.)/e.baseHeight()));e.resize().accept(Math.clamp(e.scale().getAsDouble(),.1,Math.max(.1,cap)));e.position().accept(Math.clamp(e.x().getAsInt(),2,Math.max(2,width-e.width()-2)),Math.clamp(e.y().getAsInt(),top,Math.max(top,height-e.height()-2)));}addDrawableChild(new GlassButton(uw-92,14,78,25,Text.literal("Done"),this::close));if(test!=null)addDrawableChild(new GlassButton(uw-180,14,78,25,Text.literal("Test"),test));if(picker!=null)picker.init(uw,uh);}
 public void renderBackground(DrawContext c,int mx,int my,float dt){GlassRenderer.capture();}
 public void render(DrawContext c,int mx,int my,float dt){GlassUi.drawing=true;int grip=Math.max(3,Math.round(9*ui));for(var e:elements){e.render().accept(c);int x=e.x().getAsInt(),y=e.y().getAsInt(),w=e.width(),h=e.height();c.drawStrokedRectangle(x-1,y-1,w+2,h+2,e==drag?0xffffffff:0x709999aa);GlassUi.rawRound(c,x+w-grip/2,y+h-grip/2,grip,grip,2,0xffeeeeff);}c.getMatrices().pushMatrix();c.getMatrices().scale(ui,ui);GlassUi.label(c,instruction(),10,17,Math.max(50,uw-210),22,GlassUi.TEXT);super.render(c,(int)(mx/ui),(int)(my/ui),dt);if(selected!=null){GlassUi.round(c,popupX,popupY,204,112,16,0xe024242c);GlassUi.label(c,selected.name(),popupX+8,popupY+6,188,18,GlassUi.TEXT);GlassUi.rawRound(c,popupX+12,popupY+32,180,24,8,0xff000000|selected.color().getAsInt());GlassUi.label(c,"Color",popupX+12,popupY+32,180,24,contrast(selected.color().getAsInt()));GlassUi.label(c,"Opacity: "+(int)(selected.opacity().getAsDouble()*100)+"%",popupX+12,popupY+62,180,16,GlassUi.TEXT);GlassUi.slider(c,selected,popupX+16,popupY+91,172,selected.opacity().getAsDouble(),true);}if(picker!=null){c.fill(0,0,uw,uh,0x60000000);picker.render(c,(int)(mx/ui),(int)(my/ui),dt);}c.getMatrices().popMatrix();GlassUi.drawing=false;GlassRenderer.end();}
 private int contrast(int rgb){return (rgb>>16&255)*.2126+(rgb>>8&255)*.7152+(rgb&255)*.0722>150?0xff17171b:0xffffffff;}
 private boolean inside(HudElement e,double x,double y){return x>=e.x().getAsInt()-4&&y>=e.y().getAsInt()-4&&x<=e.x().getAsInt()+e.width()+4&&y<=e.y().getAsInt()+e.height()+4;}
 public boolean mouseClicked(Click e,boolean twice){Click l=local(e);if(picker!=null)return picker.mouseClicked(l,twice);if(super.mouseClicked(l,twice))return true;if(selected!=null&&l.x()>=popupX&&l.x()<=popupX+204&&l.y()>=popupY&&l.y()<=popupY+112){if(l.y()>=popupY+32&&l.y()<=popupY+56){var target=selected;client.setScreen(new ColorPickerScreen(this,target.name(),target.color().getAsInt(),rgb->{target.tint().accept(rgb);save.run();}));}else if(l.y()>=popupY+78){alphaDrag=true;setAlpha(l.x());}return true;}selected=null;for(int i=elements.size()-1;i>=0;i--){var t=elements.get(i);if(!inside(t,e.x(),e.y()))continue;if(e.button()==1){selected=t;popupX=Math.clamp((int)l.x(),6,Math.max(6,uw-210));popupY=Math.clamp((int)l.y(),48,Math.max(48,uh-118));return true;}if(e.button()==0){drag=t;offsetX=e.x()-t.x().getAsInt();offsetY=e.y()-t.y().getAsInt();resizing=offsetX>=t.width()-8*ui&&offsetY>=t.height()-8*ui;startScale=t.scale().getAsDouble();startX=e.x();startY=e.y();originX=t.x().getAsInt();originY=t.y().getAsInt();return true;}}return clickWorld(e,twice);}
 private void setAlpha(double x){if(selected!=null)selected.alpha().accept(Math.clamp((x-popupX-16)/172.,0,1));}
 public boolean mouseDragged(Click e,double dx,double dy){if(picker!=null)return picker.mouseDragged(local(e),dx/ui,dy/ui);if(alphaDrag){setAlpha(e.x()/ui);return true;}if(drag==null)return dragWorld(e,dx,dy)||super.mouseDragged(local(e),dx/ui,dy/ui);if(resizing){double sx=(e.x()-startX)/drag.baseWidth(),sy=(e.y()-startY)/drag.baseHeight(),delta=Math.abs(sx)>=Math.abs(sy)?sx:sy;double cap=Math.min(5,Math.min((width-originX-2.)/drag.baseWidth(),(height-originY-2.)/drag.baseHeight()));drag.resize().accept(Math.clamp(startScale+delta,.1,Math.max(.1,cap)));drag.position().accept(originX,originY);}else{int x=(int)(e.x()-offsetX),y=(int)(e.y()-offsetY),cx=(width-drag.width())/2,cy=(height-drag.height())/2;if(Math.abs(x-cx)<4)x=cx;if(Math.abs(y-cy)<4)y=cy;int top=Math.round(48*ui);drag.position().accept(Math.clamp(x,2,Math.max(2,width-drag.width()-2)),Math.clamp(y,top,Math.max(top,height-drag.height()-2)));}return true;}
 public boolean mouseReleased(Click e){if(picker!=null)return picker.mouseReleased(local(e));if(drag!=null||alphaDrag){drag=null;alphaDrag=false;save.run();return true;}return releaseWorld(e)||super.mouseReleased(local(e));}
 public boolean mouseScrolled(double x,double y,double h,double v){return picker!=null?picker.mouseScrolled(x/ui,y/ui,h,v):scrollWorld(x,y,h,v)||super.mouseScrolled(x/ui,y/ui,h,v);}
 public boolean keyPressed(KeyInput key){return picker!=null?picker.keyPressed(key):super.keyPressed(key);}public void close(){if(picker!=null){picker.close();return;}save.run();client.setScreen(parent);}public boolean shouldPause(){return false;}
}
